-- Refer to https://wiki.hypr.land/configuring/core/config-options/
hl.config({
    general = {
        gaps_in  = 6,
        gaps_out = 16,

        border_size = 2,

        col = {
            -- 暖色系渐变，呼应壁纸的蜜桃/紫色调
            active_border   = { colors = {"rgba(fab387ee)", "rgba(cba6f7ee)"}, angle = 45 },
            inactive_border = "rgba(6c708655)",
            nogroup_border  = "rgba(f38ba866)",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/configuring/extra/tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 12,
        rounding_power = 2.2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 0.94,

        -- 非活动窗口轻微压暗，突出当前窗口
        dim_inactive = true,
        dim_strength = 0.12,

        shadow = {
            enabled      = true,
            range        = 14,
            render_power = 3,
            offset       = { 0, 6 },
            color        = 0x55000000,
            scale        = 1.0,
        },

        blur = {
            enabled           = true,
            variant           = "acrylic", -- 磨砂玻璃；掉帧可换回 "kawase"
            size              = 6,
            passes            = 3,
            noise             = 0.02,
            contrast          = 0.95,
            brightness        = 1.0,
            vibrancy          = 0.22,
            vibrancy_darkness = 0.1,
            xray              = true,
            ignore_opacity    = false,
            popups            = true,
            input_methods     = true,
            acrylic = {
                refraction = 20,
                clarity    = 0.40,
                bulb       = 44,
                tint       = "0x1afab387",
            },
        },
    },

    animations = {
        enabled = true,
    },
})

-- Default curves and animations, see https://wiki.hypr.land/configuring/core/animations/
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })

-- Default springs
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 238.1191, damping = 24.21279333 })
hl.curve("smooth",         { type = "spring", mass = 1, stiffness = 180,      damping = 22 })

hl.animation({ leaf = "global",        enabled = true,  speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",        enabled = true,  speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",       enabled = true,  speed = 5,    spring = "smooth" })
hl.animation({ leaf = "windowsIn",     enabled = true,  speed = 5,    spring = "smooth",       style = "popin 90%" })
hl.animation({ leaf = "windowsOut",    enabled = true,  speed = 3,    bezier = "quick",        style = "popin 90%" })
hl.animation({ leaf = "fadeIn",        enabled = true,  speed = 1.73, bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut",       enabled = true,  speed = 1.46, bezier = "almostLinear" })
hl.animation({ leaf = "fade",          enabled = true,  speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers",        enabled = true,  speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn",      enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true,  speed = 1.5,  bezier = "linear",       style = "fade" })
hl.animation({ leaf = "fadeLayersIn",  enabled = true,  speed = 1.79, bezier = "almostLinear" })
hl.animation({ leaf = "fadeLayersOut", enabled = true,  speed = 1.39, bezier = "almostLinear" })
hl.animation({ leaf = "workspaces",    enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "slidefade 20%" })
hl.animation({ leaf = "workspacesIn",  enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "slidefade 20%" })
hl.animation({ leaf = "workspacesOut", enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "slidefade 20%" })
hl.animation({ leaf = "zoomFactor",    enabled = true,  speed = 7,    bezier = "quick" })

